package com.eps.repository;

import com.eps.entity.GlVoucher;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * Spring Data JPA repository for {@link GlVoucher} entity.
 * <p>
 * Provides query methods for general ledger voucher management.
 * GL vouchers represent accounting entries generated by payment
 * processing, including debits, credits, and fees that must be
 * posted to the core banking general ledger system.
 * </p>
 *
 * <p>
 * The entity's primary key is the {@code voucherNo} field of type
 * {@link String}, uniquely identifying each accounting voucher.
 * </p>
 */
@Repository
public interface GlVoucherRepository extends JpaRepository<GlVoucher, String> {

    /**
     * Find all GL vouchers with the given posting status.
     * Supports monitoring of voucher posting pipelines and
     * identification of vouchers awaiting or failing posting.
     *
     * @param status the posting status code (e.g. PENDING, POSTED, FAILED)
     * @return list of GL vouchers in the specified posting status,
     *         never {@code null}
     */
    List<GlVoucher> findByPostStatus(String status);

    /**
     * Find all GL vouchers associated with a specific payment
     * reference. Used to retrieve the complete set of accounting
     * entries generated for a given payment instruction, including
     * principal, charges, and tax vouchers.
     *
     * @param paymentRef the payment reference identifier
     * @return list of GL vouchers linked to the specified payment,
     *         never {@code null}
     */
    List<GlVoucher> findByPaymentRef(String paymentRef);
}
